    `${BC_API}/${accountId}/buckets/${bucketId}/todos/${todoId}.json`,
    token,
    {
      method: 'PUT',
      body: JSON.stringify({
        content: title,
        due_on: dueOn,
        assignee_ids: assigneeIds,
      }),
    }
  )
  return res.ok
}

export async function completeTodo(
  accountId: number,
  token: string,
  bucketId: number,
  todoId: number
): Promise<boolean> {
  const res = await bcFetch(
    `${BC_API}/${accountId}/buckets/${bucketId}/todos/${todoId}/completion.json`,
    token,
    { method: 'POST' }
  )
  return res.ok
}

